INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90342, 'spa', 'Galaad (nombre propio)', 'Nombre propio que designa al nieto de Manasés a través de Maquir (Nm 26:29-30) y, con mucha mayor frecuencia, al territorio montañoso transjordano que lleva su nombre: una amplia meseta al este del Jordán entre el Arnón y el Yarmuk. La región era apreciada por sus ricos pastizales (Nm 32:1; Cnt 6:5), su célebre bálsamo medicinal (Jer 8:22; 46:11) y su importancia estratégica en los conflictos tribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90361, 'spa', 'Galaadita (gentilicio)', 'Galaadita (gentilicio): adjetivo gentilicio que designa a un nativo o habitante de Galaad, el territorio transjordano al este del río Jordán. Se aplica a personajes destacados como Jefté el juez (Jue 11:1, 40; 12:7), Barzilai el anciano leal (2 S 17:27; 19:31; 1 R 2:7; Esd 2:61; Neh 7:63) y Jaír el juez (Jue 10:3). Tanto las formas singular como plural (galaadita/galaaditas) comparten el mismo sentido gentilicio, identificando la procedencia de la región de Galaad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90365, 'spa', 'también, además', 'Sentido aditivo predeterminado: ''también, además, igualmente''. Eva ''dio también a su marido'' (Gn 3:6); Abel ''también trajo'' ofrenda (Gn 4:4). Con 693 ocurrencias constituye el uso abrumadoramente mayoritario. Multilingüísticamente uniforme: español también, hindi भी, árabe أيضًا, suajili pia, coreano 또한, confirmando una lectura de adición inclusiva simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90367, 'spa', 'aun, hasta, incluso', 'Sentido escalar o concesivo: ''aun, hasta, incluso'', señalando un caso inesperado o extremo en una escala de probabilidad. La evidencia multilingüe resulta diagnóstica: el suajili cambia a hata (no pia), el coreano a 심지어 (no 또한), el árabe ocasionalmente a حتّى y el español a aun (no también). Aparece prominentemente en Lv 26:44 y Dt 12:31.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90370, 'spa', 'tanto...como (correlativo)', 'Construcción correlativa pareada ''tanto...como'' (גַּם...גַּם), que vincula dos elementos paralelos. Español tanto...como, suajili wote e hindi चाहे lo marcan de forma distinta a la simple adición. Dt 32:25 emplea el par para abarcar ''tanto al joven como a la doncella'', y 1 S 2:26 lo aplica al favor ''tanto del SEÑOR como de los hombres''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90371, 'spa', 'ciertamente, en verdad', 'Uso enfático afirmativo: ''ciertamente, en verdad, de veras'', que expresa aserción fuerte en lugar de mera adición. La evidencia multilingüe resulta reveladora: hindi हाँ (sí), suajili naam (sí), coreano 참으로 (verdaderamente), árabe بل (más bien/ciertamente). En Sal 19:11-13 el salmista emplea גַּם para subrayar el valor inigualable de las ordenanzas de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90372, 'spa', '¿acaso también/aun? (retórico)', 'Uso retórico o interrogativo genuino ''¿también?/¿acaso?'' dentro de preguntas que expresan sorpresa o incredulidad. Identificable por partículas interrogativas en diversas lenguas: hindi क्या, árabe هل, español ¿acaso también? El célebre ''¿También Saúl entre los profetas?'' (1 S 10:11-12; 19:24) y la exclamación asombrada de Agar (Gn 16:13) son paradigmáticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90373, 'spa', 'ni, tampoco (negativo)', 'Uso en polaridad negativa que significa ''ni, tampoco'' cuando aparece en contextos negativos. Se distingue nítidamente en múltiples lenguas: suajili wala, español ni, hindi न तो — todas formas dedicadas de conjunción negativa en lugar de aditiva. Presente en pasajes como 1 S 28:6 donde el SEÑOR no respondió a Saúl ''ni por sueños, ni por Urim, ni por profetas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90380, 'spa', 'porque también (causal)', 'Raro compuesto causal בְּשַׁגַּם que significa ''porque también, por cuanto'', atestiguado únicamente en Gn 6:3 donde Dios limita la longevidad humana. Español porque también, hindi क्योंकि, árabe لأنّه y suajili kwa sababu pia convergen en una lectura causal, confirmando que se trata de una fusión gramaticalizada única de preposición, partícula relativa y גַּם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90384, 'spa', 'Papiro, junco acuático', 'Papiro o junco: la caña alta y acuática (Cyperus papyrus) propia de riberas pantanosas, empleada como material para cestas y barcas. Su nombre podría derivar de una raíz que significa ''absorber agua''. La cesta de Moisés es una tevat gome (Éx 2:3); Isaías 18:2 menciona embarcaciones de papiro; Job 8:11 lo empareja con la hierba de pantano; Isaías 35:7 lo muestra floreciendo en el desierto restaurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90387, 'spa', 'Retribución, recompensa', 'Retribución, recompensa: pago, recompensa o retribución por las obras, típicamente con connotación negativa de castigo justo que recae sobre el autor. Jueces 9:16 pregunta si Abimelec fue tratado ''conforme a la obra de sus manos,'' y el Salmo 137:8 declara bienaventurado a quien dé a Babilonia su merecido. Joel 4:4 e Isaías 59:18 lo usan para la justicia retributiva de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90392, 'spa', 'Beneficio, bondad', 'Beneficio, bondad: un beneficio, bondad o trato generoso — el lado positivo del actuar de Dios con su pueblo. El Salmo 103:2 es el pasaje clave: ''Bendice, alma mía, al SEÑOR, y no olvides ninguno de sus beneficios.'' En 2 Crónicas 32:25, Ezequías no respondió ''conforme al beneficio'' que le había sido hecho, mostrando ingratitud ante la gracia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90399, 'spa', 'Retribución o recompensa', 'Retribución, recompensa o pago que se recibe conforme a las propias acciones. En 2 Samuel 19:36 significa la recompensa debida al servicio fiel. En Isaías 59:18 se refiere a la retribución divina según las obras (en plural, «retribuciones»). En Jeremías 51:56 la expresión «Dios de las retribuciones» (אֵל גְּמֻלוֹת) subraya el carácter de Dios como justo pagador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90401, 'spa', 'Destetar a un niño — Destetar a un niño de la leche materna, marcando la transic', 'Destetar a un niño — Destetar a un niño de la leche materna, marcando la transición de la infancia a la alimentación independiente. Sara destetó a Isaac con una fiesta (Gn 21:8), y Ana pospuso su peregrinación hasta haber destetado a Samuel (1 S 1:22-23). El español emplea el verbo específico ''destetar'', mostrando que este sentido tiene vocabulario propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90404, 'spa', 'Hacer bien, ser generoso — Actuar con generosidad hacia alguien, sin la lógica e', 'Hacer bien, ser generoso — Actuar con generosidad hacia alguien, sin la lógica estricta de reciprocidad del sentido de retribución. El salmista suplica ''Haz bien a tu siervo'' (Sal 119:17) y testifica ''Me ha hecho bien'' (Sal 13:6; 116:7). Pr 11:17 dice que el misericordioso ''hace bien a su propia alma''. Expresa bondad llevada a plenitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90406, 'spa', 'Retribuir, recompensar — Dar en proporción a lo recibido, sea para bien o para m', 'Retribuir, recompensar — Dar en proporción a lo recibido, sea para bien o para mal. Los hijos de Jacob temen que José les ''pague'' su crueldad (Gn 50:15, 17), y David pregunta ''¿He pagado mal a mi aliado?'' (1 S 24:17). Dt 32:6 lo emplea para la ingratitud de Israel. El sentido recíproco domina este uso, abarcando tanto la recompensa como la venganza divina y humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90433, 'spa', 'Madurar, dar fruto — Llevar el fruto a su madurez, dicho de plantas que completa', 'Madurar, dar fruto — Llevar el fruto a su madurez, dicho de plantas que completan su ciclo de crecimiento. La vara de Aarón ''produjo almendras maduras'' (Nm 17:8), e Is 18:5 habla de un brote que ''madura en uva''. Este uso agrícola preserva la idea central del verbo: un proceso natural que alcanza su plenitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90437, 'spa', 'camello (animal doméstico)', 'camello (animal doméstico)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90461, 'spa', 'Gamaliel (nombre propio)', 'Nombre personal del príncipe designado de la tribu de Manasés durante el período del desierto. Sus cinco apariciones se hallan en Números dentro de fórmulas tribales estereotipadas: la lista censal (1:10), la disposición del campamento (2:20), las ofrendas de dedicación del tabernáculo (7:54, 59) y el orden de marcha (10:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90462, 'spa', 'Cesar, acabarse', 'Llegar a su fin, cesar, no ser más. Usado intransitivamente en lamentos y preguntas retóricas sobre la desaparición de la fidelidad y la misericordia. Presente en Sal 7:9, Sal 12:1 y Sal 77:8, donde aparece en paralelo con términos como אָפֵס (''desaparecer'') y פָּסַס (''desvanecerse''). Las traducciones ''ha cesado'' en español y ''has ceased'' en inglés confirman la fuerza intransitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90464, 'spa', 'Gomer', 'Como nombre propio, Gomer abarca dos referentes. En la tradición genealógica, es hijo de Jafet y padre de Askenaz, Rifat y Togarmá (Gn 10:2-3; 1 Cr 1:5-6), asociado con los cimerios de Anatolia. Ezequiel 38:6 lo incluye entre los aliados de Gog. El segundo referente es la esposa de Oseas (Os 1:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90466, 'spa', 'Gemarías (nombre propio)', 'Nombre propio, Gemarías (''Yah ha cumplido''). Designa a dos individuos: (a) hijo de Safán, funcionario simpatizante en cuya cámara del templo Baruc leyó el rollo de Jeremías (Jer 36:10-12, 25); (b) hijo de Hilcías, enviado diplomático que llevó la carta de Jeremías a los exiliados en Babilonia (Jer 29:3). Las transliteraciones confirman la forma consistente ''Gemarías/Gemaryahu''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90467, 'spa', 'Jardín, huerto cultivado — Terreno cultivado y cercado, ya sea para agricultura,', 'Jardín, huerto cultivado — Terreno cultivado y cercado, ya sea para agricultura, recreo o propósito sagrado. Este sentido abrumadoramente dominante se traduce uniformemente como jardín/huerto en todas las lenguas. Anclado en la narrativa del Edén (Gn 2:8-16), jardines reales (2 R 21:18; Est 1:5; 7:7), la amada como ''jardín cerrado'' (Cnt 4:12), e imágenes proféticas de jardines restaurados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90482, 'spa', 'Jardín (topónimo) — Uso como nombre propio o topónimo, ''el Jardín'' como nombre d', 'Jardín (topónimo) — Uso como nombre propio o topónimo, ''el Jardín'' como nombre de lugar (Beth-haggán o ha-Ganná). Atestiguado en 2 Reyes 9:27, donde el contexto describe a Ocozías huyendo ''por el camino de la casa del jardín''. La distinción entre nombre común y propio sugiere que la audiencia antigua reconocía este como un lugar específico cerca de Jezreel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90490, 'spa', 'Robar, hurtar — Sentido activo principal en Qal', 'Robar, hurtar — Sentido activo principal en Qal: robar, cometer hurto, tomar ilegalmente lo ajeno. Domina las ocurrencias y abarca todo el canon, desde la prohibición del Decálogo (Éx 20:15; Lv 19:11) hasta la acusación de Jacob contra Labán (Gn 31:26-30) y la transgresión en Jericó (Jos 7:11). El robo de los ídolos de Labán por Raquel ejemplifica la amplitud de este sentido central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90497, 'spa', 'Ladrón, el que roba — Uso participial sustantivado', 'Ladrón, el que roba — Uso participial sustantivado: el ladrón, el que roba, como categoría social o legal. En Dt 24:7 y Zac 5:3 el participio identifica al agente que comete hurto. Jeremías 23:30 acusa a los falsos profetas que ''roban'' las palabras de Dios unos de otros, marcándolos como ladrones habituales de la palabra divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90499, 'spa', 'Ser robado — Las formas pasivas (Nifal y Pual) que expresan el estado o evento d', 'Ser robado — Las formas pasivas (Nifal y Pual) que expresan el estado o evento de ser robado. José dice al copero ''fui robado de la tierra de los hebreos'' (Gn 40:15), y Jacob reclama a Labán por lo ''robado'' del rebaño (Gn 31:39). Éxodo 22:12 usa el Nifal para legislar sobre bienes sustraídos de un depósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90504, 'spa', 'Escabullirse, escurrirse — La forma reflexiva hitpael', 'Escabullirse, escurrirse — La forma reflexiva hitpael: escabullirse, retirarse furtivamente. En 2 Samuel 19:3 los soldados de David ''se escabulleron'' en la ciudad avergonzados tras la victoria que mató a Absalón. Job 4:12 usa el Pual para describir una palabra que ''fue traída furtivamente'' a Elifaz, susurrada en secreto en una visión nocturna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90510, 'spa', 'Secuestrar, robar personas — Robar a una persona, es decir, secuestrar o raptar', 'Secuestrar, robar personas — Robar a una persona, es decir, secuestrar o raptar. Éxodo 21:16 prescribe la muerte para quien ''robe a un hombre'', y Deuteronomio 24:7 especifica la misma pena por secuestrar a un israelita. Absalón ''robó los corazones'' de los hombres de Israel (2 S 15:6), un secuestro metafórico de lealtades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90526, 'spa', 'Ladrón, salteador', 'Ladrón, salteador: persona que roba bienes o personas; usado para ladrones literales, secuestradores y figuras metafóricas de sigilo y apoderamiento ilícito. El término abarca asaltantes nocturnos (Éx 22:2), traficantes de esclavos (Dt 24:7) e imágenes proféticas de invasión furtiva (Joel 2:9; Abd 5). Todas las principales tradiciones de traducción emplean un solo lexema central: ladrón, voleur, Dieb.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90538, 'spa', 'jardín, huerto — Jardín u huerto cultivado y cercado, generalmente irrigado y fé', 'jardín, huerto — Jardín u huerto cultivado y cercado, generalmente irrigado y fértil. Se emplea como figura de bendición y abundancia (Nm 24:6; Ecl 2:5; Is 58:11), pero también de sitios de culto idolátrico (Is 1:29; 65:3; 66:17). Las doce ocurrencias apuntan a un solo concepto hortícola unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90546, 'spa', 'Jardín, huerto cultivado', 'Jardín o huerto: espacio cultivado y cercado, usado para jardines reales y huertos íntimos. Aparece como ginnat bitan (''jardín del pabellón'') en Est 1:5; 7:7–8, escenario palaciego donde se desencadena la caída de Amán, y como ginnat egoz (''huerto de nogales'') en Cantares 6:11, imagen de belleza y descubrimiento. El término transmite siempre el sentido de un recinto cuidado y delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90547, 'spa', 'Cofres o tesoros', 'Cofres (arcas de almacenamiento) o tesoros (depósitos reales), con tres apariciones contextuales. Ezequiel 27:24 emplea el constructo «cofres de telas multicolores» en el inventario comercial de Tiro. Ester 3:9 y 4:7 se refieren a «los tesoros del rey» donde Amán depositaría su soborno. La evidencia interlingüística muestra la dualidad cofres/tesoros según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90548, 'spa', 'Tesorerías reales', 'Sustantivo arameo que designa tesoros o tesorerías, usado tres veces en Esdras en contextos de administración real persa. Esdras 5:17 y 6:1 emplean «casa de los tesoros del rey» para referirse al edificio de archivos en Babilonia. Esdras 7:20 usa la forma constructa «casa de los tesoros del rey» como fuente de financiamiento para las necesidades del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90551, 'spa', 'Defender, proteger (Qal)', 'Defender o proteger cubriendo y rodeando, dicho exclusivamente de la acción divina en favor de Jerusalén o del pueblo de Dios. Las traducciones al español lo vierten como ''defenderé/defenderá'', confirmando el sentido protector consistente en las ocho apariciones. El verbo aparece tanto en Qal como en Hifil sin diferencia semántica perceptible, siempre acompañado de vocabulario de salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90554, 'spa', 'Nombre sacerdotal', 'Nombre propio de un sacerdote entre los repatriados postexílicos, que aparece tres veces en Nehemías con ligeras variaciones ortográficas. Nehemías 10:6 registra «Ginetoi», mientras que 12:4 enumera «Ginetón» y 12:16 usa la forma preposicional «de Ginetón». Las variantes reflejan la fluidez ortográfica típica de los nombres propios en los textos postexílicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90557, 'spa', 'aborrecer, detestar — Aborrecimiento activo y visceral', 'aborrecer, detestar — Aborrecimiento activo y visceral: sentir un asco intenso hacia alguien o algo. Cinco de las ocho ocurrencias se agrupan en el discurso de maldiciones del pacto de Levítico 26, donde tanto Dios como Israel son sujeto de esta repulsión (Lv 26:11, 15, 30, 43, 44). Ezequiel 16:45 lo aplica a mujeres que «aborrecen» a sus maridos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90561, 'spa', 'ser contaminado, ser rechazado — Nifal pasivo', 'ser contaminado, ser rechazado — Nifal pasivo: ser desechado como impuro o ritualmente rechazado. En la elegía de David por Saúl y Jonatán, el escudo de los héroes «fue contaminado» en el monte Gilboa (2 S 1:21), manchado de sangre y despojado de su honor sagrado. La voz pasiva y el vocabulario de contaminación lo distinguen del aborrecimiento activo del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90563, 'spa', 'fallar, malograrse — Hifil causativo', 'fallar, malograrse — Hifil causativo: fallar o malograrse, referido a un proceso biológico que deja de funcionar. Job 21:10 describe la vaca del impío que cría con éxito y «no falla», la única ocurrencia en esta conjugación, pasando de la repulsión emocional al fracaso reproductivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90567, 'spa', 'Gaal (nombre propio)', 'Gaal: nombre propio de un insurgente cananeo, hijo de Ebed, que desafió brevemente el control de Abimelec sobre Siquem. Limitado por completo a Jueces 9:26-41, Gaal llegó a Siquem, ganó la confianza de los líderes locales durante una fiesta de vendimia y declaró públicamente su disposición a derrocar a Abimelec (Jue 9:28-29). Zebul alertó secretamente a Abimelec, quien emboscó a las fuerzas de Gaal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90569, 'spa', 'Reprender, censurar', 'Reprender o censurar severamente, expresando fuerte desaprobación o corrección autoritativa. Abarca tanto la reprensión humana — un padre que amonesta a su hijo (Gn 37:10), segadores advertidos de no molestar a Rut (Rt 2:16) — como la reprensión divina donde la palabra de Dios tiene fuerza cósmica, aquietando mares (Sal 106:9; Nah 1:4) y silenciando al acusador (Zac 3:2). La traducción uniforme en español, francés y alemán confirma su cohesión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90582, 'spa', 'Reprensión, censura, amenaza', 'Una censura verbal severa o reprensión amenazante, ya sea humana o divina. Cuando la pronuncian personas, lleva la fuerza correctiva de la sabiduría (Pr 13:1, 8; 17:10; Ec 7:5). Cuando la emite Dios, se convierte en un arma cósmica: la reprensión de Yahvé seca mares (Is 50:2; Sal 104:7), expone los cimientos de la tierra (2 S 22:16; Sal 18:15) y deja a los guerreros sin vida (Sal 76:6). Las traducciones multilingües confirman uniformemente este campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90593, 'spa', 'sacudir, temblar, agitar — Sacudida violenta, temblor o agitación, referido a co', 'sacudir, temblar, agitar — Sacudida violenta, temblor o agitación, referido a convulsiones cósmicas y naturales. El Qal describe la tierra temblando en la teofanía (Sal 18:8 = 2 S 22:8), mientras que el Hitpael intensifica el movimiento como un vaivén aplicado tanto a montes que se estremecen ante la presencia de Dios como a aguas encrespadas: las olas del mar que no pueden traspasar su límite (Jer 5:22) y las crecidas del Nilo (Jer 46:7-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90598, 'spa', 'tambalearse, vacilar (figurado) — Tambaleo o vacilación figurados bajo el juicio', 'tambalearse, vacilar (figurado) — Tambaleo o vacilación figurados bajo el juicio divino. En Jeremías 25:16, la forma Hitpoel wehitgo''ashu describe a naciones que beben la copa de la ira de YHWH y luego «se tambalean», una extensión del sacudimiento físico de un terremoto a la desorientación y el colapso de los pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90602, 'spa', 'Monte Gaas', 'Gaas: montaña en el territorio de Efraín, al sur de Timnat-sera, señalada como referencia junto a la sepultura de Josué (Jos 24:30; Jue 2:9). Sus barrancos (nahale Gaas) figuran en las listas de los guerreros de David (2 S 23:30; 1 Cr 11:32). El nombre puede relacionarse con la raíz g-ʿ-sh (''temblar''), sugiriendo un pico agreste o sacudido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90603, 'spa', 'Jefe edomita', 'Nombre propio de un jefe edomita (aluf), hijo de Elifaz y nieto de Esaú. Aparece en Génesis 36:11, 16 y en la genealogía paralela de 1 Crónicas 1:36. La evidencia interlingüística preserva el nombre de forma consistente en todas las traducciones. La conjunción «y Gatam» indica su inclusión en las listas de jefes edomitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90604, 'spa', 'Cuerpo, persona sola', 'Cuerpo o persona considerada como entidad física individual, usado en el modismo begappo (''por sí solo, sin compañía'') en las leyes de esclavos de Éx 21:3–4. La expresión indica entrar o salir de la servidumbre sin acompañantes. El español ''en su soltería'' refleja bien el matiz de soledad corporal. Es cognado del hebreo tardío y arameo guf (''cuerpo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90605, 'spa', 'Alas de bestias', 'Sustantivo arameo para ala o alas, que aparece tres veces en las visiones de bestias de Daniel 7. Daniel 7:4 menciona las alas dos veces: primero «sus alas» de la primera bestia, luego las alas siendo arrancadas. Daniel 7:6 describe cuatro alas en la bestia semejante a un leopardo. Las alas simbolizan conquista veloz y poder imperial en el lenguaje visionario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90606, 'spa', 'vid, parra', 'vid, parra');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90631, 'spa', 'Azufre', 'Azufre, sustancia mineral combustible de origen natural usada a lo largo de las Escrituras como imagen principal de la destrucción punitiva divina. La aparición paradigmática es Génesis 19:24, donde Yahvé hace llover גָּפְרִית y fuego sobre Sodoma. Reaparece en oráculos de juicio: el Salmo 11:6 advierte que los impíos recibirán fuego y azufre como su porción, y Deuteronomio 29:23 describe tierra calcinada con azufre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90637, 'spa', 'Forastero, extranjero residente', 'Forastero, extranjero residente: persona no nativa que habita entre los israelitas sin herencia ancestral de tierras, dependiente de la hospitalidad comunitaria y sujeto a protecciones específicas de la Torá. Abraham en Hebrón (Gn 23:4) y Moisés en Madián (Éx 2:22) ejemplifican esta condición. Las traducciones multilingües — español ''extranjero'', francés ''étranger-résident'', alemán ''Fremdling'' — convergen en la idea de un forastero protegido que depende de la gracia del pueblo anfitrión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90666, 'spa', 'Gera (nombre propio)', 'Gera: nombre propio benjaminita que funciona tanto como nombre personal como designación de clan. Listado entre los hijos de Benjamín en Gn 46:21 y como descendiente de Bela en 1 Cr 8:3, 5, 7, el nombre probablemente llegó a denotar una familia benjaminita prominente. Su importancia radica en dos célebres ''hijos de Gera'': el juez Aod y Simei, quien maldijo a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90668, 'spa', 'Enfermedad cutánea', 'Enfermedad cutánea costrosa o comezón que aparece en tres contextos legales y de pacto. Levítico 21:20 la enumera como descalificación sacerdotal, Levítico 22:22 como defecto en animales de sacrificio, y Deuteronomio 28:27 como maldición del pacto («la sarna de Egipto»). El término refleja una condición ritualmente contaminante y físicamente incurable en el contexto bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90669, 'spa', 'Nombre propio bíblico', 'Nombre propio de persona y de lugar que aparece en tres contextos. Como persona, Gareb fue uno de los valientes de David (2 Sam 23:38 = 1 Cr 11:40). Como lugar, el collado de Gareb (גִּבְעַת גָּרֵב) señala el límite de Jerusalén en la profecía de restauración de Jeremías 31:39.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90671, 'spa', 'Cuello ornamental', 'Cuello o garganta — la parte frontal del cuello vista como lugar para llevar adornos, usada exclusivamente en Proverbios como figura de la sabiduría interiorizada. La instrucción es «collar para tu cuello» (Prov 1:9), la misericordia y la verdad se atan «a tu cuello» (3:3), y los mandamientos se convierten en «gracia para tu cuello» (3:22; 6:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90672, 'spa', 'Gergeseo (pueblo)', 'Los gergeseos, grupo étnico contado entre las siete naciones cananeas destinadas al desplazamiento por Israel. Listados como engendrados por Canaán en la Tabla de las Naciones (Gn 10:16 = 1 Cr 1:14), aparecen en promesas de pacto (Gn 15:21, Neh 9:8) y narrativas de conquista (Dt 7:1, Jos 3:10, Jos 24:11). Su ubicación territorial nunca se especifica, lo que los convierte en el más oscuro de los siete pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90679, 'spa', 'provocar, contender', 'Provocar o contender con alguien (Hitpael, hostilidad general). Dios ordena a Israel: «No contendáis con ellos» respecto a los descendientes de Esaú (Dt 2:5), Moab (Dt 2:9) y Amón (Dt 2:19). Ezequías advierte a Amasías: «¿Por qué provocas tu propia ruina?» (2 R 14:10). Refleja antagonismo interpersonal o nacional sin implicar necesariamente acción militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90680, 'spa', 'suscitar, incitar', 'Suscitar o incitar contienda (Piel, causativo). El trío proverbial: el iracundo «suscita» contiendas (Pr 15:18; 29:22), y el avaro «incita» peleas (Pr 28:25). El tema Piel marca al sujeto como instigador que provoca a otros al conflicto, a diferencia del Hitpael donde el sujeto mismo participa activamente en la lucha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90682, 'spa', 'hacer guerra, preparar batalla', 'Hacer guerra o prepararse para la batalla (Hitpael, militar). En las visiones apocalípticas de Daniel, los reyes «se levantan» para campañas militares: «sus hijos harán guerra» (Dn 11:10) y el rey del sur «se preparará para guerra» (Dn 11:25). Se distingue de la provocación más general por su vocabulario marcialmente específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90690, 'spa', 'rumia — Rumia, el alimento parcialmente digerido que los animales rumiantes regu', 'rumia — Rumia, el alimento parcialmente digerido que los animales rumiantes regurgitan y mastican por segunda vez. Se usa exclusivamente en las leyes dietéticas mosaicas (Lv 11:3-7, 26; Dt 14:6-8) como uno de los dos criterios que definen a los animales terrestres puros. La fórmula «que rumia» (מַעֲלַת גֵּרָה) aparece con cada animal evaluado. Los que rumian pero carecen de pezuña hendida (camello, liebre, damán) y los de pezuña hendida que no rumian (cerdo) son declarados impuros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90693, 'spa', 'Unidad de peso', 'La gera, unidad mínima de peso israelita, equivalente a un vigésimo de siclo. Sus cinco apariciones bíblicas se enmarcan en definiciones legales formales del siclo, ya sea para contribuciones al santuario (Ex 30:13), precios de redención levítica (Nm 3:47; 18:16) o las normas del templo visionario de Ezequiel (Ez 45:12). Cognado con el asirio giru, representa una fracción estandarizada que se ha conservado como préstamo léxico en múltiples lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90694, 'spa', 'Garganta', 'La garganta como órgano interno de producción vocal y deglución. El Salmo 69:3 lamenta ''mi garganta se ha secado'' de tanto clamar a Dios. El Salmo 5:9 la usa como metáfora del habla mortífera: ''su garganta es un sepulcro abierto''. El Salmo 149:6 coloca alabanzas ''en su garganta'', e Isaías 58:1 ordena la proclamación profética a plena voz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90697, 'spa', 'Cuello', 'El cuello como parte exterior visible del cuerpo, sujeta a ornamentación o exhibición postural. Isaías 3:16 describe a las hijas de Sion caminando con ''cuello estirado'', postura de altivez. Ezequiel 16:11 representa a Dios colocando una cadena ''sobre tu cuello'' como adorno nupcial. El árabe unuq (''cuello'') y el español cuello confirman la referencia externa y visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90704, 'spa', 'Monte de bendición', 'Monte en las tierras altas centrales de Israel, al sur de Siquem y frente al monte Ebal, designado como monte de la bendición en la ceremonia mosaica del pacto (Dt 11:29; 27:12). Josué 8:33 registra la lectura del pacto allí, y Jueces 9:7 sitúa la parábola de Jotam en sus laderas. Se identifica hoy con Jebel et-Tur.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90705, 'spa', 'Hacha para talar', 'Herramienta de corte, específicamente un hacha usada para talar árboles y labrar madera. Las cuatro apariciones apuntan a un instrumento estándar de leñador: la cabeza del hacha que se desprende (Dt 19:5), herramienta de asedio prohibida contra árboles frutales (Dt 20:19), la notable ausencia de ruido de hacha en la construcción del templo (1 R 6:7) y el hacha personificada de Asiria (Is 10:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90708, 'spa', 'Hueso, estructura ósea', 'Hueso, armazón esquelético. El sentido concreto anatómico aparece en Job 40:18 al describir los miembros del Behemot como tubos de bronce, en paralelo con עֶצֶם. Proverbios 17:22 y 25:15 lo usan colectivamente para referirse a la complexión corporal. El arameo geram y el árabe jirm (''cuerpo'') confirman la fisicalidad de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90711, 'spa', 'Era, lugar de trilla — Área abierta, típicamente en una colina o terreno elevado', 'Era, lugar de trilla — Área abierta, típicamente en una colina o terreno elevado, donde se trilla y avienta el grano cosechado. La traducción uniforme en todas las lenguas — español ''era'', francés ''aire'', alemán ''Tenne'' — confirma un referente agrícola único y estable en las 36 ocurrencias. Pasajes clave incluyen la procesión fúnebre de Jacob, la era de Arauna y las advertencias proféticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90725, 'spa', 'Garganta (variante Ketiv) — Variante del Ketiv (texto consonántico) en Jeremías ', 'Garganta (variante Ketiv) — Variante del Ketiv (texto consonántico) en Jeremías 2:25, donde la forma escrita se lee como גָּרוֹן (''garganta'') en lugar del Qere גֹּרֶן (''era''). El contexto — ''detén tu pie de andar descalza y tu garganta de la sed'' — confirma esta lectura anatómica. Esta variante textual muestra la divergencia entre tradición escrita y lectura sinagogal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90733, 'spa', 'Sentido pasivo Nifal de ser disminuido, descontado o retirado — 7 apariciones co', 'Sentido pasivo Nifal de ser disminuido, descontado o retirado — 7 apariciones concentradas en contextos legales y administrativos. En Éxodo 5:11, la provisión de paja de los israelitas «no será disminuida»; en Levítico 27:18, la tasación de un campo «será descontada» proporcionalmente; en Números 27:4 y 36:3, las herencias tribales corren riesgo de ser «retiradas» por arreglos matrimoniales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90734, 'spa', 'Sentido activo Qal nuclear de disminuir, reducir o sustraer de una cantidad', 'Sentido activo Qal nuclear de disminuir, reducir o sustraer de una cantidad. Domina con 11 apariciones en contextos legislativos, narrativos y sapienciales. Faraón ordena «no disminuiréis los ladrillos» (Éx 5:8, 19); Deuteronomio prohíbe dos veces quitar de los mandamientos de Dios (Dt 4:2; 12:32); Eclesiastés hace eco de que nadie puede quitar de lo que Dios hace (Ec 3:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90736, 'spa', 'Participio pasivo Qal que describe el trasquilado o corte del cabello como ritua', 'Participio pasivo Qal que describe el trasquilado o corte del cabello como ritual de duelo. Solo dos apariciones, ambas en oráculos proféticos paralelos contra Moab (Is 15:2; Jer 48:37), donde las barbas se describen como גְּרוּעָה — «trasquiladas» o «cortadas». La evidencia multilingüe marca un giro léxico claro, pasando del vocabulario de sustracción al de corte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90741, 'spa', 'Una sola aparición Qal en Job 15', 'Una sola aparición Qal en Job 15:8 donde Elifaz pregunta a Job si «retiene» o «acapara» la sabiduría para sí mismo. El sentido no es reducción numérica sino más bien monopolización — retener la sabiduría impidiendo que otros la tengan. El español «retienes» selecciona vocabulario de control y retención en lugar de términos de sustracción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90743, 'spa', 'Una sola aparición Piel en Job 36', 'Una sola aparición Piel en Job 36:27 donde Dios «extrae hacia arriba» las gotas de agua que se destilan como lluvia. El sentido físico de tirar hacia arriba es notablemente distinto de la disminución. La raíz intensiva Piel puede preservar un significado concreto más antiguo de «tirar hacia fuera o extraer» que evolucionó hacia el más abstracto «reducir».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90754, 'spa', 'Arrastrar por la fuerza', 'Arrastrar, barrer con violencia. Se usa para describir capturas violentas: el pescador caldeo arrastra naciones en su red (Hab 1:15) y la violencia de los impíos los arrastra (Pr 21:7). El cognado asirio gararu (''correr, arrastrar'') respalda este como el sentido primario de la raíz, que implica un movimiento lineal enérgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90755, 'spa', 'Gerar (topónimo) — Nombre propio de una antigua ciudad filistea en el Néguev, al', 'Gerar (topónimo) — Nombre propio de una antigua ciudad filistea en el Néguev, al sur de Gaza, asociada con las estadías patriarcales de Abraham (Gn 20:1-2) e Isaac (Gn 26:1, 6). También aparece en la tabla de las naciones como límite cananeo (Gn 10:19) y en la campaña militar de Asa (2 Cr 14:12-13). Las diez ocurrencias se refieren al mismo sitio geográfico, con variantes preposicionales (en Gerar, a Gerar, de Gerar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90761, 'spa', 'Expulsar, echar fuera — Expulsar o echar fuera con fuerza', 'Expulsar, echar fuera — Expulsar o echar fuera con fuerza: sentido dominante que abarca la expulsión de Adán del Edén (Gn 3:24), la expulsión de los pueblos cananeos ante Israel (Éx 34:11; Jue 2:3; 1 Cr 17:21) y el destierro de individuos como Agar (Gn 21:10). También cubre el papel de Moisés en obligar a Faraón a liberar a Israel (Éx 6:1; 11:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90762, 'spa', 'Mujer divorciada — Participio pasivo Qal גְּרוּשָׁה usado en cinco textos legale', 'Mujer divorciada — Participio pasivo Qal גְּרוּשָׁה usado en cinco textos legales sacerdotales (Lv 21:7, 14; 22:13; Nm 30:9; Ez 44:22). El término aparece junto a ''viuda'' (אַלְמָנָה) para definir categorías de mujeres con quienes los sacerdotes pueden o no casarse. La metáfora subyacente de ser ''echada'' del esposo permanece viva en el participio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90772, 'spa', 'Ser expulsado, ser desterrado — Formas pasivas Nifal y Pual', 'Ser expulsado, ser desterrado — Formas pasivas Nifal y Pual: ser expulsado o desterrado. Jonás 2:4 clama ''fui arrojado de tu presencia'', los israelitas son echados de Egipto con prisa (Éx 12:39), y Job 30:5 describe a marginados expulsados de la sociedad. La voz pasiva subraya la indefensión de los expulsados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90778, 'spa', 'Agitar, arrojar, lanzar — Del agua que se agita, se revuelve y arroja desechos', 'Agitar, arrojar, lanzar — Del agua que se agita, se revuelve y arroja desechos. Isaías 57:20 compara a los impíos con un mar agitado que no puede reposar y cuyas olas arrojan cieno e inmundicia. Amós 8:8 emplea la raíz para la tierra que se agita y baja como el Nilo. Extensión metafórica distintiva que evoca turbulencia incesante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90802, 'spa', 'Gershom (nombre propio)', 'El nombre propio hebreo Gershom (גֵּרְשֹׁם), etimológicamente vinculado a גּוּר (''peregrinar''). Identifica principalmente al primogénito de Moisés (Éx 2:22; 18:3; Jue 18:30), pero también a un jefe de linaje levítico escrito a veces Gershón (1 Cr 6:16-17; 15:7; 23:15-16; 26:24) y a un ancestro de los que regresaron con Esdras (Esd 8:2). La leve variación ortográfica entre גֵּרְשֹׁם y גֵּרְשׁוֹם en los manuscritos refleja diferencias escribales sin distinción semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90808, 'spa', 'Gersón', 'Gersón: nombre propio גֵּרְשׁוֹן, también escrito גֵּרְשֹׁם, que designa al hijo primogénito de Leví y al antepasado epónimo del clan levítico gersonita. La frase ''hijos de Gersón'' es una designación formularia de las responsabilidades del clan en el transporte del tabernáculo, presente en Números, Josué y Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90812, 'spa', 'gersonita (designación de clan)', 'Gentilicio para el clan de Gershón, que funciona como sustantivo colectivo («los gersonitas», Nm 3:21, 23; 4:24, 27) o como adjetivo individual («el gersonita», 1 Cr 26:21). Las 13 ocurrencias designan linaje levítico sin relación semántica con la raíz g-r-sh (''expulsar''). El término aparece con artículo como colectivo sustantivado en Números y Josué, y como modificador individual en Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90818, 'spa', 'Gesur (topónimo)', 'Nombre propio de un territorio arameo y su pueblo, ubicado al este del alto Jordán, entre Galaad y el monte Hermón. Las traducciones lo rinden como ''Gesur'' o ''Guesur'' en español, con prefijos preposicionales que reflejan movimiento hacia o residencia en esa tierra. El nombre posiblemente significa ''puente'' o ''tierra de puentes'', acorde con su posición como zona de tránsito entre Aram e Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90823, 'spa', 'Gentilicio de Gesur', 'Designación gentilicia para los habitantes de Gesur, un pequeño territorio arameo situado en la ribera nororiental del mar de Galilea. Con el artículo definido (הַגְּשׁוּרִי), funciona como sustantivo colectivo para la población de esa región. En español se emplea tanto en singular como en plural: ''el gesureo'' y ''los gesureos''. Los pasajes clave se encuentran en Deuteronomio 3:14 y Josué 13:11-13.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90825, 'spa', 'Lluvia, precipitación — Lluvia o precipitación en general', 'Lluvia, precipitación — Lluvia o precipitación en general: el término ordinario y no marcado para la lluvia en hebreo, que abarca lloviznas, lluvias estacionales y aguaceros sostenidos. Usado en narrativa (Gn 7:12; 8:2), ley (Lv 26:4), profecía (Os 6:3; Jl 2:23), sabiduría (Pr 25:14, 23) y poesía (Cnt 2:11). Todas las traducciones principales usan su palabra básica para lluvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90830, 'spa', 'Aguacero, lluvia intensa — Aguacero o lluvia fuerte e intensa', 'Aguacero, lluvia intensa — Aguacero o lluvia fuerte e intensa: una intensificación marcada más allá de la precipitación ordinaria. Atestiguado en Zac 10:1 (''Pedid al SEÑOR lluvia en la estación de la lluvia tardía''), donde la evidencia multilingüe se separa notablemente del sentido 1: el español usa ''aguacero'' en vez de ''lluvia'', indicando que los traductores percibieron una fuerza inusualmente concentrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90836, 'spa', 'Adversario árabe', 'Nombre personal de un líder árabe que se opuso a la reconstrucción de los muros de Jerusalén por parte de Nehemías, apareciendo como Gesem y Gasmu. Figura constantemente junto a Sanbalat y Tobías como parte de una triple oposición (Neh 2:19; 6:1–2, 6). La variante Gasmu en 6:6 puede reflejar la forma árabe o nabatea original del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90837, 'spa', 'Cuerpo (arameo)', 'El cuerpo físico de una persona o criatura, empleado en las porciones arameas de Daniel. El sustantivo גְּשֵׁם (gueshem) aparece con sufijos pronominales tanto en singular como en plural: ''su cuerpo'' (Dan 4:33; 5:21; 7:11) y ''sus cuerpos'' (Dan 3:27-28). En español se traduce directamente como ''cuerpo'' y ''sus cuerpos'', sin las complicaciones de las variantes ketiv y qere del texto hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90842, 'spa', 'Gosén (topónimo)', 'El topónimo propio Gosén, que se refiere principalmente a la fértil región del delta egipcio donde Israel se asentó durante su estancia (Gn 45:10; 46:28-29; 47:1-6; 50:8) y fue milagrosamente preservada de las plagas (Éx 8:22; 9:26), y secundariamente a una región y ciudad en el sur de Judá (Jos 10:41; 11:16; 15:51). Las glosas en todas las lenguas transliteran el topónimo con mínima variación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90848, 'spa', 'Lagar', 'El lagar, instalación agrícola donde las uvas se trituran mediante el pisado. Usado literalmente para el procesamiento de la uva (Jue 6:11; Neh 13:15) y como potente metáfora del juicio divino, en que Dios pisa a las naciones como uvas (Is 63:2; Lm 1:15; Jl 3:13). Este uso figurado se proyecta hasta Apocalipsis 14:19-20.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90849, 'spa', 'Gat (ciudad filistea) — Nombre propio de una ciudad filistea mayor, una de la pe', 'Gat (ciudad filistea) — Nombre propio de una ciudad filistea mayor, una de la pentápolis junto a Gaza, Ascalón, Asdod y Ecrón. Famosa como ciudad natal de Goliat (1 S 17:4), lugar del exilio de David bajo Aquis (1 S 21:10; 27:2) y escenario del proverbial lamento ''No lo anunciéis en Gat'' (2 S 1:20). Aparece también en Amós 6:2 como ejemplo admonitorio. Etimológicamente significa ''lagar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90856, 'spa', 'Guitita (gentilicio) — Adjetivo gentilicio que significa ''de Gat, perteneciente ', 'Guitita (gentilicio) — Adjetivo gentilicio que significa ''de Gat, perteneciente a Gat'', usado para identificar a individuos o grupos originarios de la ciudad filistea de Gat. Se aplica en singular a Obed-edom (2 Sam 6:10-11), Itai (2 Sam 15:19, 22) y al gigante muerto por Elhanán (2 Sam 21:19), y en plural al contingente guitita que marchó con David (2 Sam 15:18) o que aparece entre los pueblos filisteos (Jos 13:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90859, 'spa', 'Término musical técnico', 'Término musical técnico presente en los encabezados de tres salmos (Sal 8:1, 81:1, 84:1), acompañado de la preposición «sobre la Guitit». Las interpretaciones varían: (1) un instrumento de Gat (lira guitita), (2) un tipo de melodía, o (3) posiblemente «lagares» (si se lee גִּתּוֹת), lo cual sugeriría música de la fiesta de la vendimia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90861, 'spa', 'Ciudad levítica', 'Ciudad levítica en la asignación tribal de Dan, cuyo nombre significa «lagar de la granada». Fue una de las ciudades asignadas al clan coatita de los levitas (Jos 21:24; 1 Cr 6:69). La segunda aparición en Josué 21:25, situada en Manasés, se considera ampliamente una corrupción textual por Ibleam. El sitio permanece sin identificación arqueológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90862, 'spa', 'Esta, esa (demostrativo)', 'Función demostrativa básica —''esta'' o ''esa''— que señala un referente específico y contextualmente relevante. Las cinco apariciones abarcan visiones y narraciones de Daniel: ''¿No es esta la gran Babilonia?'' (Dan 4:30), las bestias que diferían unas de otras (Dan 7:3) y ''este cuerno'' (Dan 7:8). Las traducciones convergen en demostrativos simples: ''esta'' o ''este'' en español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90864, 'spa', 'La otra (contrastivo)', 'Uso contrastivo o recíproco con la preposición lamed, formando la expresión idiomática da leda (''una contra otra''). En Daniel 5:6, las rodillas de Belsasar golpean ''una contra la otra'' al ver la escritura en la pared. En español, ''contra la otra'' resalta la relación adversativa y recíproca entre elementos emparejados, más allá de la simple deixis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90866, 'spa', 'Languidecer, desfallecer', 'Languidecer, desfallecer o debilitarse a causa de aflicción, hambre o pena. El Salmo 88:9 describe el ojo que se apaga (דָּאֲבָה) por la aflicción. Jeremías 31:12 promete que «no volverán a languidecer» (לֹא יוֹסִיפוּ לְדַאֲבָה). Jeremías 31:25 usa «alma desfallecida» (נֶפֶשׁ דָּאֲבָה), aunque se debate si es forma verbal o adjetival.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90869, 'spa', 'Estar ansioso, preocuparse', 'Estar ansioso, preocupado, inquieto o temeroso, describiendo la turbación interior de aprensión ante circunstancias o personas. El rango abarca la preocupación paternal natural (1 Sam 9:5; 10:2, donde el padre de Saúl se angustia por sus hijos), la aflicción existencial por el pecado (Sal 38:18), la serena libertad de ansiedad para el justo (Jer 17:8, en paralelo con ירא), y el pavor ante otra persona (Is 57:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90876, 'spa', 'Doeg (nombre propio)', 'Nombre personal de un edomita al servicio de Saúl, que posiblemente significa ''ansioso'' o ''temeroso''. Las nueve apariciones se refieren al mismo individuo. El español conserva la forma ''Doeg'', mientras que el francés y el alemán mantienen la forma hebrea junto a la transliteración. Su historia se desarrolla íntegramente en 1 Samuel 21-22 y el título del Salmo 52, componiendo un retrato breve pero devastador de la traición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90880, 'spa', 'Ansiedad, preocupación', 'Ansiedad emocional o preocupación inquieta que pesa sobre el corazón. El sustantivo דְּאָגָה (de''agá) abarca desde la inquietud personal hasta el temor comunitario. En español se traduce como ''ansiedad'' y ''preocupación'', captando ambas dimensiones. En Proverbios 12:25 describe una carga emocional personal, mientras que en Ezequiel 4:16 y 12:18-19 se empareja con ''espanto'' (שִׁמָּמוֹן) y ''temblor'' para expresar el terror colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90884, 'spa', 'Vuelo veloz', 'Volar velozmente o lanzarse en picada, representando un movimiento rápido y vertiginoso por el aire. Usado en símil militar de una nación que desciende como águila sobre Israel (Dt 28:49), del juicio divino que se abate sobre Moab y Edom con alas desplegadas (Jer 48:40; 49:22), y de Yahvé surcando las alas del viento en teofanía (Sal 18:10). El verbo evoca velocidad depredadora y poder devastador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90886, 'spa', 'Oso (animal) — El oso pardo sirio, empleado tanto en sentido literal (el encuent', 'Oso (animal) — El oso pardo sirio, empleado tanto en sentido literal (el encuentro de David, 1 Sam 17:34; la maldición de Eliseo, 2 Re 2:24) como figurado para representar ferocidad y peligro (una osa privada de sus cachorros, Prov 17:12; Os 13:8; la bestia imperial, Dan 7:5; el reino de paz, Is 11:7). Las traducciones en diversas lenguas confirman un único referente zoológico en ambos registros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90897, 'spa', 'Calumnia, infamia', 'Murmuración, calumnia, difamación o informe maligno: habla maliciosa diseñada para dañar la reputación de alguien o desalentar la acción. El español emplea ''calumnia'' y ''difamación'', captando la fuerza difamatoria, mientras el francés usa ''calomnie''. El rango semántico abarca desde el chisme privado y malicioso (Sal 31:13; Jer 20:10) hasta la difusión pública de un informe perjudicial (Gn 37:2; Nm 13:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90905, 'spa', 'Abeja', 'La abeja melífera, tanto como insecto literal como figura de persecución hostil en enjambre. Aparece literalmente en el episodio del cadáver del león de Sansón (Jue 14:8). Se usa figuradamente para enemigos que persiguen implacablemente como un enjambre: los amorreos persiguiendo a Israel (Dt 1:44), enemigos rodeando en el Salmo 118:12, y Dios convocando a Asiria representada como silbar para llamar a la abeja (Is 7:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90906, 'spa', 'Débora (nombre propio) — Nombre propio hebreo (דְּבוֹרָה, ''abeja''), que designa ', 'Débora (nombre propio) — Nombre propio hebreo (דְּבוֹרָה, ''abeja''), que designa principalmente a dos mujeres: (1) la querida nodriza de Rebeca, llorada en Betel bajo la ''Encina del Llanto'' (Gn 35:8), y (2) la profetisa y jueza de Israel que convocó a Barac para la batalla contra Sísara (Jue 4:4-14) y celebró la victoria en el Cántico de Débora (Jue 5:1, 7, 12). Ocho de las diez apariciones corresponden a la profetisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90912, 'spa', 'Santuario interior', 'Santuario interior: la habitación más interna del Templo de Salomón (דְּבִיר), el Lugar Santísimo donde el Arca de la Alianza reposaba bajo las alas de los querubines. Derivado de una raíz que sugiere ''parte trasera,'' se refiere a la cámara posterior protegida por puertas de madera de olivo y revestida enteramente de oro (1 Re 6:16, 19-23, 31). El término aparece casi exclusivamente en la narrativa de la construcción del Templo (1 Re 6-8; 2 Cr 3-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90923, 'spa', 'Debir (topónimo)', 'El topónimo propio Debir, que designa una ciudad-estado cananea específica en las tierras altas de Judá. Aparece en narrativas de conquista (Jos 10:38-39; 11:21; 12:13), listas de fronteras tribales (Jos 15:15, 49), el episodio de Otoniel (Jue 1:11-13) y asignaciones de ciudades levíticas (Jos 21:15; 1 Cr 6:43). La forma direccional Debira ocurre en Jos 10:38. Una ocurrencia en Jos 10:3 nombra a Debir como nombre personal de un rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90928, 'spa', 'Torta de higos prensados', 'Torta prensada de higos secos, empleada como provisión alimenticia y aplicación medicinal. Servía como ración portátil (1 S 25:18; 30:12; 1 Cr 12:40) y como cataplasma curativa aplicada al divieso de Ezequías (2 R 20:7 = Is 38:21). Cognado con el árabe dubla (''masa, bocado'') y el griego παλάθη, lo que apunta a una tecnología alimentaria común del Cercano Oriente antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90930, 'spa', 'Aferrarse en devoción', 'Aferrarse en devoción: Qal relacional, adherirse a una persona, a Dios o a un grupo por lealtad, devoción o fidelidad al pacto. Abarca desde el vínculo matrimonial primordial (''se unirá el hombre a su mujer'', Gn 2:24) pasando por la teología del pacto (''te apegarás a Yahvé tu Dios'', Dt 10:20; Jos 23:8) hasta la emblemática declaración de Rut (Rut 1:14; 2:8, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90932, 'spa', 'Pegarse físicamente', 'Pegarse físicamente: Qal físico, adherirse o pegarse materialmente — la lengua al paladar, la piel a los huesos, la ropa al cuerpo, una enfermedad aferrándose a una persona. Abarca imágenes corporales (Job 19:20, ''mi hueso se pega a mi piel''; Sal 137:6, ''que mi lengua se pegue a mi paladar''; Lm 4:4) y juicio divino (Dt 28:60, enfermedades que se ''pegan'' a Israel).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90935, 'spa', 'Pegarse entre sí (pasivo)', 'Pegarse entre sí (pasivo): Pual/Hofal pasivo, estar pegado, unido o hecho adherir — la voz pasiva de la adhesión física. Las escamas del Leviatán ''se pegan'' tan firmemente que no pasa aire entre ellas (Job 41:17, 23), los terrones de polvo ''se adhieren'' (Job 38:38) y los huesos del salmista ''se pegan'' en colapso desamparado (Sal 22:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90939, 'spa', 'Hacer pegar, causar adherencia', 'Hacer pegar, causar adherencia: Hifil causativo de adhesión, hacer que algo se pegue o se adhiera — Dios haciendo que una maldición, una plaga o un compromiso se adhiera a alguien. Dios ''hará que la pestilencia se te pegue'' (Dt 28:21), Dios ''hizo que el cinturón se adhiriera'' a la cintura de Jeremías como señal profética (Jer 13:11), y Dios ''hará que tu lengua se pegue a tu paladar'' para silenciar a Ezequiel (Ez 3:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90947, 'spa', 'Perseguir de cerca, alcanzar', 'Perseguir de cerca, alcanzar: Hifil de persecución, acosar de cerca y alcanzar — usado en contextos de persecución militar y de calamidades que alcanzan a alguien. Predomina en narrativas bélicas: Labán persiguiendo a Jacob (Gn 31:23), los filisteos acosando a Saúl (1 S 31:2), tribus israelitas persiguiendo a Benjamín (Jue 20:42, 45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90979, 'spa', 'Juntura o soldadura', 'La juntura, soldadura o unión donde las cosas se conectan. Isaías 41:7 lo usa en metalurgia: la soldadura (הַדֶּבֶק) que une las partes de un ídolo. 1 Reyes 22:34 y 2 Crónicas 18:33 usan el plural «las junturas» (הַדְּבָקִים) para la armadura de Acab, específicamente «entre las junturas y la coraza», la brecha vulnerable donde penetró la flecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90980, 'spa', 'Adherido, aferrado', 'Adjetivo o participio que significa adherido, aferrado o unido estrechamente. Deuteronomio 4:4 usa el participio plural «los que se aferran» (הַדְּבֵקִים) con la preposición בְּ: quienes se mantienen fieles a Yahvé. 2 Crónicas 3:12 emplea el femenino singular «unida» (דְּבֵקָה) con לְ: el ala del querubín adherida a otra. Proverbios 18:24 usa el masculino singular «más unido» (דָּבֵק): un amigo más leal que un hermano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (90981, 'spa', 'hablar, decir (Piel)', 'El sentido abrumadoramente dominante (1.105×), que abarca todas las formas del Piel: perfecto, imperfecto, imperativo, infinitivo y participio. Cubre toda comunicación verbal activa. La fórmula וַיְדַבֵּר יְהוָה introduce el discurso divino centenares de veces desde Génesis 8:15 en adelante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91004, 'spa', 'hablante (Qal ptc.)', 'El participio activo Qal usado sustantivamente para designar «el que habla, el hablante» (28×). Su función agentiva se confirma en todas las lenguas. Destaca en Génesis 16:13, donde Agar identifica a Dios como «el que me habla», y en Éxodo 6:29, donde Moisés es «el que habla ante Faraón».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91042, 'spa', 'someter, sujetar (Hifil)', 'Raíz homónima distinta דבר II en el tronco Hifil, con el sentido de «someter, subyugar» (4×). El Salmo 18:47 («Él somete pueblos debajo de mí») y el Salmo 47:3 («Él sujeta naciones») son los casos más claros. Proverbios 16:13 y Amós 5:10 muestran contextos forenses o autoritativos afines.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91057, 'spa', 'hablar, deliberar', 'Dos apariciones raras (Sal 119:23; Mal 3:16) que se sitúan en el límite entre el habla ordinaria y el discurso deliberativo. En el Salmo 119:23, los príncipes «se sientan y hablan contra mí», insinuando calumnia o conspiración. En Malaquías 3:16, los que temen al SEÑOR «hablaron entre sí», sugiriendo conversación íntima y reverente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91070, 'spa', 'hablar, emanar (voz media)', 'Dos apariciones (Nm 7:89; Ez 43:6) que implican un habla reflexiva o de voz media: la voz divina que «habla» desde entre los querubines, con matiz hitpaeliano. Estos pasajes describen la voz de Dios percibida como fenómeno auditivo continuo, más que como un enunciado dirigido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91095, 'spa', 'ser dicho (Pual)', 'El tronco pasivo Pual (2×): «cosas gloriosas son dichas de ti» (Sal 87:3) y «el día en que se hable de ella» (Cnt 8:8). Ambos pasajes se refieren a algo declarado o hablado acerca de un sujeto, enfatizando el contenido recibido más que el agente que lo produce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91116, 'spa', 'destruir, aniquilar', 'Una única aparición en 2 Crónicas 22:10, donde Atalía «destruyó» la descendencia real. Esto no es habla sino aniquilación. Probablemente refleja דבר III (relacionado con דֶּבֶר «pestilencia») o una superposición textual y semántica con el acadio dabāru «ahuyentar». El sentido destructivo se aparta por completo de las acepciones comunicativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91131, 'spa', 'palabra, enunciado', 'Variante del sentido primario: una palabra hablada o escrita, un oráculo divino o un mensaje profético. Este subgrupo se distingue por patrones distribucionales específicos dentro del mismo campo semántico de la comunicación verbal, confirmado por las glosas multilingües.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91136, 'spa', 'hechos, actos, crónicas', 'Hechos, actos o crónicas: el plural דְּבָרִים como registro de lo que alguien hizo, no solo dijo. Se encuentra en la fórmula recurrente «lo demás de los hechos de [rey]» (1 R 11:41) y en contextos donde los «actos» constituyen el legado histórico de un reinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91143, 'spa', 'cosa, algo, nada', 'Un «algo» o «cosa» indefinido, especialmente en construcciones negadas que significan «nada en absoluto». Lot dice «no puedo hacer cosa alguna» (Gn 19:8), las regulaciones especifican «toda cosa que resista el fuego» (Nm 31:23) y las acusaciones señalan «no faltaba cosa alguna» (Éx 9:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91148, 'spa', 'asunto, cuestión', 'Un asunto, cuestión o incumbencia que exige atención práctica. Cubre casos legales (Gn 12:17, «el SEÑOR hirió a Faraón por causa del asunto de Sarai»), problemas situacionales (Gn 20:11) y asuntos administrativos (Gn 24:9). El contexto desplaza דָּבָר del enunciado al objeto tratado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91157, 'spa', 'sucesos, acontecimientos', 'Eventos o sucesos: «las cosas que ocurrieron». En construcciones plurales como «después de estas cosas» (Gn 15:1; 22:1; 22:20), דָּבָר funciona como «acontecimientos» más que como «palabras». Este sentido refleja la unidad hebrea entre palabra y realidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91179, 'spa', 'modo, manera, costumbre', 'Modo, manera o costumbre, usado comparativamente con el sentido de «conforme a esta manera» o «tal cosa». Aparece en «¿No hará justicia el Juez de toda la tierra?» (Gn 18:25) y en advertencias deuteronómicas: «no se volverá a hacer tal cosa» (Dt 13:11; 19:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91209, 'spa', 'causa, razón, motivo', 'Causa, razón o motivo, usado en construcciones preposicionales que significan «a causa de» o «por motivo de». Se encuentra en formulaciones legales deuteronómicas: «por causa de este asunto» (Dt 22:24; 23:4) y en la narración de Rajab: «si divulgáis este asunto nuestro» (Jos 2:14, 20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91277, 'spa', 'Pestilencia, plaga', 'Pestilencia, plaga: enfermedad epidémica mortal entendida como instrumento divino de juicio o castigo del pacto, frecuentemente emparejada con la espada (חֶרֶב) y el hambre (רָעָב) en la fórmula profética de triple catástrofe (Jer 14:12; 21:7; Ez 5:12). Amenazada primero contra Egipto (Éx 5:3; 9:3, 15), recurre en las advertencias del desierto (Nm 14:12), las maldiciones deuteronómicas (Dt 28:21) y el juicio del censo de David (2 S 24:13-15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91292, 'spa', 'Causa, razón u orden', 'Causa, razón u orden establecido. Se emplea preposicionalmente como עַל דִּבְרַת con el sentido de ''a causa de, por motivo de'' (Ecl 3:18; 7:14; 8:2), y en Sal 110:4 como ''según el orden de'' Melquisedec, denotando un rango sacerdotal. En Job 5:8 significa ''mi causa'', el asunto presentado ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91297, 'spa', 'Ciudad levítica', 'Ciudad levítica en el territorio de Isacar, identificada con la actual Deburije al pie del monte Tabor. Josué 19:12 emplea la forma con artículo definido en las descripciones de límites. Josué 21:28 y 1 Crónicas 6:72 la incluyen entre las ciudades levíticas sin artículo. Las traducciones interlingüísticas conservan el nombre con ligeras variantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91298, 'spa', 'Miel', 'Miel: sustancia natural dulce que abarca la miel de abeja encontrada silvestre en rocas y bosques (Dt 32:13; Jue 14:8-9) y posiblemente miel de dátil o jarabe de fruta como producto comercial (Gn 43:11; Ez 27:17). Usada literalmente como alimento y figuradamente para la dulzura del habla divina (Sal 19:10) y la promesa del pacto de abundancia agrícola (''que fluye leche y miel'', Éx 3:8). Las 54 apariciones forman un solo grupo semántico coherente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91307, 'spa', 'Pez (criatura acuática)', 'Pez (criatura acuática): pez o peces, la criatura acuática común de mares, ríos y lagos. Usado para el gran pez que tragó a Jonás (Jon 2:1), para los peces como parte del orden creado junto a las bestias y las aves (Gén 9:2; Sal 8:9; Os 4:3), y para los peces como objeto de comercio y alimento (Neh 13:16). El plural דְּגֵי הַיָּם (''peces del mar'') es la expresión colectiva estándar. Job 12:8 invita a preguntar a los peces como testigos de la obra creadora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91319, 'spa', 'pez (sustantivo colectivo)', 'Sustantivo femenino colectivo para pez como clase zoológica de criaturas acuáticas, distinguido del masculino דָּג que puede designar peces individuales. Se usa en el mandato de la creación (Gn 1:26, 28), la plaga del Nilo (Éx 7:18, 21), la memoria nostálgica de los alimentos de Egipto (Nm 11:5), la prohibición de ídolos con forma de pez (Dt 4:18) y el río escatológico de Ezequiel (Ez 47:9-10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91329, 'spa', 'Dagón', 'El teónimo Dagón, que nombra al dios principal de los filisteos. Las 13 ocurrencias funcionan como nombre propio divino en contextos cultuales o narrativos: el templo de Dagón (bet Dagón, 1 S 5:2, 5; 1 Cr 10:10), los sacerdotes de Dagón (1 S 5:5), Dagón como ídolo derribado ante el arca (1 S 5:3-4) y la fiesta a Dagón en Gaza (Jue 16:23). Las traducciones transliteran uniformemente: Dagón en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91332, 'spa', 'Enarbolar estandartes', 'Verbo denominativo de דֶּגֶל (''estandarte''): enarbolar banderas o estar dispuesto con estandartes. El Salmo 20:5 usa el imperfecto de primera persona plural נִדְגֹּל (''enarbolaremos nuestras banderas'') en celebración de la salvación divina. Cantares 6:4 y 6:10 emplea el participio Nifal femenino plural נִדְגָּלוֹת (''las abanderadas''): «imponente como ejércitos con estandartes», para describir la majestuosa belleza de la amada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91333, 'spa', 'bandera, estandarte', 'Estandarte militar o tribal que designa las cuatro grandes divisiones del campamento israelita en el desierto. Se usa casi exclusivamente en Números (1:52; 2:2-34; 10:14-25) para describir la disposición organizada de las tribus alrededor del tabernáculo, cada división agrupada bajo su propio דֶּגֶל junto con sus señales tribales (אֹתֹת). La única aparición figurada en Cantares 2:4 —«su bandera sobre mí es amor»— transforma el símbolo militar en metáfora de protección amorosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91338, 'spa', 'Grano, cereal — Producto de cereal cultivado (especialmente trigo y cebada) como', 'Grano, cereal — Producto de cereal cultivado (especialmente trigo y cebada) como categoría de riqueza agrícola y bendición divina. Aparece característicamente en la tríada דָּגָן-תִּירוֹשׁ-יִצְהָר (''grano, mosto, aceite'') que representa la abundancia plena de la Tierra Prometida (Dt 7:13; 11:14; 28:51; Os 2:8-9; Jl 2:19). La bendición de Isaac invoca דָּגָן como señal del favor divino (Gn 27:28, 37). Los profetas usan su retiro como señal de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91350, 'spa', 'Pecho femenino', 'El pecho o pezón femenino, usado tanto en contextos de intimidad conyugal legítima como en alegoría profética de infidelidad espiritual. En Proverbios 5:19 describe los pechos de la esposa amada como fuente de deleite continuo. En Ezequiel 23:3, 8, 21 aparece en la alegoría gráfica de Aholá (Samaria) y Aholibá (Jerusalén), donde el manoseo de los pechos representa alianzas políticas y religiosas ilícitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91352, 'spa', 'Dedán — Nombre propio que designa tanto a un pueblo como a su territorio en Arab', 'Dedán — Nombre propio que designa tanto a un pueblo como a su territorio en Arabia, trazado genealógicamente hasta Cus a través de Raama (Gn 10:7) y hasta Abraham a través de Cetura (Gn 25:3). Ezequiel retrata a Dedán como una potencia mercantil que comerciaba con Tiro en monturas y artículos preciosos (Ez 27:15, 20), al tiempo que pronuncia juicio sobre la región (Ez 25:13). Su emparejamiento con Sabá (Ez 38:13) sitúa a Dedán en las principales rutas caravaneras del noroeste de Arabia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91358, 'spa', 'Oro como metal precioso en arameo, abarcando estatuas reales (Dan 2', 'Oro como metal precioso en arameo, abarcando estatuas reales (Dan 2:32; 3:1), vasos del templo confiscados y restituidos (Dan 5:2-3; Esd 5:14; 6:5) y tesoro para la reconstrucción (Esd 7:15-18). Tanto la forma enfática dahabā como la absoluta dehab designan la misma sustancia. El español ''oro'' y el alemán ''Gold'' confirman un sentido único e indiviso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91368, 'spa', 'Amado, amante', 'Amado, amante: persona amada, amante romántico o ser querido. Es el sentido dominante, concentrado casi exclusivamente en el Cantar de los Cantares, donde la mujer se dirige a su compañero como dodí (''mi amado'') en pasajes como Cnt 1:13-14, 2:3 y 2:8-10. La evidencia interlingüística confirma el registro romántico: español ''amado'', árabe حَبِيب (habib), hindi प्रीतम (preetam).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91369, 'spa', 'Tío, hermano del padre', 'Tío, hermano del padre: tío paterno o pariente varón cercano. Este sentido aparece en material legal y narrativo: Levítico 10:4 (Uziel, tío de Aarón), Levítico 20:20 y 25:49 (leyes sobre las obligaciones de un pariente), y 1 Samuel 10:14-16 (el tío de Saúl interrogándole). La evidencia multilingüe traza una línea clara respecto al sentido romántico: español ''tío'', hindi चाचा (chacha).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91372, 'spa', 'Amor, caricias', 'Amor, caricias: amor, caricias o acto amoroso como sustantivo abstracto, típicamente en la forma plural dodim. Proverbios 7:18 invita ''saciémonos de amores (dodim)'', mientras que Cantar 1:2 declara ''tus amores (dodekha) son mejores que el vino''. El español distingue esto con el plural ''amores'', el hindi con प्रेम (prem, el concepto de amor) y el suajili con upendo (amor como estado).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91389, 'spa', 'Cesta, canasta', 'Cesta o recipiente abierto empleado para transportar mercancías. En Jeremías 24:1-2, dos cestas (דּוּדִים) de higos —unos buenos, otros podridos— sirven como señal profética. En 2 Reyes 10:7, la misma palabra describe las canastas en que se colocaron las cabezas de los setenta hijos de Acab. La evidencia multilingüe converge con fuerza: inglés «basket», español «cesta/canasta» y equivalentes árabes apuntan a un recipiente de transporte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91391, 'spa', 'Olla, caldero', 'Olla, caldero o marmita usada para hervir alimentos. En 1 Samuel 2:14, el siervo del sacerdote clava el garfio en la olla (בַּדּוּד) para reclamar la carne de la ofrenda, enumerada junto a parur, qallachath y kiyyor como utensilios de cocina. En 2 Crónicas 35:13, las ofrendas pascuales se hierven en דּוּדִים junto a otras ollas y sartenes. Job 41:20 emplea la imagen de una olla hirviente para describir el aliento del Leviatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91396, 'spa', 'David (nombre propio)', 'Nombre propio del segundo rey de Israel, hijo de Isaí, ungido en Belén (1 S 16:13), conquistador de Jerusalén, receptor de la alianza dinástica eterna (2 S 7) y autor tradicional de los Salmos. Sus 1.075 apariciones se distribuyen entre variantes ortográficas (דָּוִד / דָּוִיד), pero la evidencia interlingüística es unánime: todas las lenguas lo transcriben como «David».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91406, 'spa', 'Tía paterna', 'Tía, específicamente la hermana del padre o la esposa del hermano del padre. Éxodo 6:20 identifica a Jocabed como la tía de Amram (דֹּדָתוֹ, ''su tía''), con quien se casó antes de la ley levítica. Levítico 18:14 prohíbe acercarse a ''tu tía'' (דֹּדָתְךָ), la esposa del hermano del padre. Levítico 20:20 prohíbe acostarse con ''su tía'' (דֹּדָתוֹ).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91407, 'spa', 'Dodo (nombre propio)', 'Nombre propio masculino (דּוֹדוֹ, Dodo) que significa ''su amado'', posiblemente con matices teofóricos vinculados al nombre divino ''Dod'' atestiguado en inscripciones moabitas. En español se transcribe como ''Dodo'' o ''Dodó'' (con acento). El nombre está asociado al ámbito militar-heroico de los jueces y los valientes de David. La lectura ketiv דֹּדִי en 2 Samuel 23:9 sugiere una forma alternativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91411, 'spa', 'Mandrágoras', 'La planta de mandrágora o su fruto, asociados con el amor y la fertilidad. En Génesis 30:14-16, Rubén recoge mandrágoras durante la siega del trigo y Raquel negocia con Lea por ellas, un episodio impregnado de la antigua creencia de que las mandrágoras favorecen la concepción. Cantares 7:14 invoca su aroma como imagen del deseo romántico. La evidencia multilingüe es notablemente consistente: español «mandrágoras», inglés «mandrakes».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91412, 'spa', 'Cestas (variante homógrafa)', 'Forma homógrafa poco frecuente que aparece solo en Jeremías 24:1, donde la grafía consonántica דּוּדָאֵי se emplea en la construcción «cestas de higos» en vez de «mandrágoras». Inglés «baskets-of», español «cestas-de» y cognados árabes convergen en un significado de recipiente. BDB trata esta forma como relacionada con דּוּד (H1731, olla/cesta) y no con la palabra para mandrágora, y el contexto — una visión profética de cestas de higos — confirma esta lectura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91419, 'spa', 'Desfallecido, enfermo', 'Desfallecido, enfermo, languideciente. Se emplea para describir agotamiento emocional o espiritual, como en Lam 1:13 donde Jerusalén queda desolada y desfallecida, y en Lam 5:17 donde el corazón enferma de dolor. El paralelismo con שׁוֹמֵמָה (desolada) en Lam 1:13 subraya la totalidad del abatimiento. El término abarca desde la enfermedad física hasta la impureza ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91420, 'spa', 'Enjuagar, limpiar', 'Enjuagar, lavar, limpiar con agua. Se emplea literalmente para el lavado de animales sacrificiales en las pilas del templo (Ez 40:38; 2 Cr 4:6) y figuradamente para la limpieza divina de culpa e impureza moral (Is 4:4). El Afel arameo y el acadio diku confirman el sentido causativo de enjuagar. Jer 51:34 presenta una variante textual disputada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91422, 'spa', 'Corazón desfalleciente', 'Adjetivo que significa desfalleciente o enfermo, usado exclusivamente con ''corazón'' (לֵב) para expresar agotamiento emocional y espiritual. Isaías 1:5 lo emplea en reprensión: «todo el corazón está desfalleciente» (כָל־לֵבָב דַּוָּי), en paralelo con «toda la cabeza está enferma». Jeremías 8:18 y Lamentaciones 1:22 expresan angustia personal: «mi corazón desfallece dentro de mí» (עָלַי לִבִּי דַוָּי).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91426, 'spa', 'Nombre personal', 'Como nombre personal, un hijo de Ismael enumerado en la Tabla de las Naciones (Gn 25:14; 1 Cr 1:30), probablemente asociado con el importante oasis árabe de Dumat al-Yandal en la región de al-Yawf. El nombre puede subyacer también a los usos geográficos y simbólicos, ya que los nombres tribales ismaelitas frecuentemente se convirtieron en topónimos a lo largo de las rutas del desierto arábigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91427, 'spa', 'Espera silenciosa', 'Espera silenciosa y confiada ante Dios; quietud contemplativa del alma que expresa resignación y fe. En el Salmo 62:1 denota el reposo tranquilo del alma solo en Dios, mientras que el Salmo 65:1 empareja este silencio con la alabanza como forma de adoración. El Salmo 39:2 lo usa para la contención deliberada —callar aun cuando se es provocado— y el Salmo 22:2 describe la ausencia de reposo o alivio del dolor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91428, 'spa', 'Silencio o mudez', 'Silencio o el adverbio ''en silencio'', presente en tres contextos proféticos. Isaías 47:5 ordena a Babilonia: «siéntate en silencio» (שְׁבִי דוּמָם). Lamentaciones 3:26 lo usa con conjunción: «y (esperar) en silencio» (וְדוּמָם) la salvación. Habacuc 2:19 describe «una piedra de silencio» (אֶבֶן דוּמָם), un ídolo mudo e incapaz de hablar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91429, 'spa', 'Cera derretible', 'Cera como sustancia que se funde, empleada exclusivamente en símiles de disolución ante el poder divino o el fuego. Los montes se derriten como cera en la teofanía (Sal 97:5; Miq 1:4), los impíos perecen como cera ante la llama (Sal 68:2) y el corazón del sufriente se vuelve cera dentro de él (Sal 22:14). La asociación constante con el derretimiento hace de esta palabra una imagen emblemática de la fragilidad y transitoriedad ante la presencia soberana de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91432, 'spa', 'habitar, residir', 'Habitar o residir en un lugar, abarcando tanto usos verbales finitos («habitar, habitaban») como el participio sustantivado («moradores, habitantes»). En Dn 4:9 y 4:18, las bestias del campo y las aves del cielo habitan (tedur, yedurun) en y sobre un árbol cósmico. En Dn 2:38, 3:31, 4:32 y 6:26, la forma participial darey/darin aparece en la frase «todos los moradores de la tierra», expresando habitación universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91444, 'spa', 'generación, contemporáneos', 'Una generación como grupo de contemporáneos: las personas vivas al mismo tiempo, caracterizadas como cohorte moral o espiritual. ''Esta generación'' puede ser justa (Gn 7:1, donde Noé destaca en la suya) o perversa (Dt 32:5, 20; Sal 12:7). Precedida frecuentemente por artículo o demostrativo, funciona casi como sustantivo colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91446, 'spa', 'generaciones, posteridad', 'Generaciones sucesivas, posteridad, empleado en plural con sufijos posesivos en la legislación cultual y pactal para expresar una obligación vinculante sobre todos los descendientes. La fórmula לְדֹרֹתָם/לְדֹרֹתֵיכֶם (''por sus/vuestras generaciones'') impregna la ley pentateucal: circuncisión (Gn 17:7, 12), Pascua (Éx 12:14), Shabat (Éx 31:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91452, 'spa', 'perpetuidad, por los siglos', 'Perpetuidad, era tras era: la fórmula distributiva מִדּוֹר לְדוֹר o לְדוֹר וָדוֹר (''de generación en generación''), que expresa la duración infinita o la cualidad eterna de la fidelidad de Dios (Sal 100:5), de su nombre (Éx 3:15) o de su trono (Lm 5:19). No es un término demográfico sino temporal: דּוֹר como unidad de tiempo sin fin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91480, 'spa', 'morada, habitación', 'Morada o habitación: sentido raro, posiblemente un homónimo distinto, que aparece en Isaías 38:12, donde Ezequías lamenta ''mi morada ha sido arrancada y removida de mí como tienda de pastor''. BDB lo vincula a una raíz diferente (דור, ''habitar, rodear''), y algunos estudiosos lo tratan como un lexema independiente. Única aparición clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91491, 'spa', 'Dor (ciudad costera)', 'Dor, ciudad costera cananea sobre el Mediterráneo al sur del monte Carmelo, asignada a Manasés pero nunca plenamente conquistada (Jue 1:27; 1 Cr 7:29). Figura entre los reyes derrotados por Josué (Jos 12:23) y se menciona en la narración de la coalición norteña (Jos 11:2). El compuesto Nafat-Dor o Nafot-Dor (Jos 11:2; 12:23; 1 Re 4:11) se refiere al distrito circundante o las alturas costeras. Bajo Salomón fue uno de los doce distritos administrativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91493, 'spa', 'trillar grano', 'El proceso agrícola de trillar grano, separando los granos de las cáscaras pisoteando o usando un trillo. Deuteronomio 25:4 («no pondrás bozal al buey que trilla») y la escena de Ornán trillando trigo (1 Cr 21:20) anclan este uso literal. La imagen de Isaías 28:27-28 sobre diferentes técnicas de trilla muestra el rico conocimiento agrícola que subyace al término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91496, 'spa', 'pisotear, aplastar', 'Pisoteo o aplastamiento metafórico, típicamente en contextos de juicio divino o militar contra pueblos o naciones. Moab es hollado «como se pisa la paja» en el fango (Is 25:10), Habacuc envisiona a Dios pisoteando naciones en su ira (Hab 3:12), y Miqueas exhorta a Sión a levantarse y trillar a sus enemigos (Mi 4:13). El español distingue entre «trillar» literal y «pisotear» figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91508, 'spa', 'Nifal', 'Nifal: desterrado, expulsado — Participio nifal usado como sustantivo: un desterrado o expatriado, alguien que ha sido arrojado al exilio. Isaías 11:12 y 56:8 prometen que Dios reunirá ''a los desterrados de Israel'', y el Salmo 147:2 celebra esa misma reunión. El término destaca el estado permanente de desplazamiento más que el acto de empujar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91510, 'spa', 'Qal', 'Qal: empujar, arrojar, expulsar — Empujar, arrojar o expulsar activamente a una persona mediante fuerza física. El Salmo 118:13 usa el infinitivo absoluto duplicado para expresar un empujón violento (''me empujaste con fuerza para hacerme caer''), y el Salmo 140:5 describe maquinaciones ''para hacer tropezar mis pies''. El árabe daha (''lanzar, propulsar'') preserva la energía cinética bruta de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91512, 'spa', 'Nifal/Pual', 'Nifal/Pual: ser derribado, ser abatido — Formas pasivas que indican ser derribado con fuerza, ser derrocado o tambalearse. Los malvados son ''abatidos'' en su calamidad (Prov 14:32), los malhechores caen y ''son derribados'' sin poder levantarse (Sal 36:12), y un muro inclinado se compara con algo a punto de ''desplomarse'' (Sal 62:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91520, 'spa', 'Terrorífico, espantoso', 'Terrorífico, espantoso (participio pasivo): describe algo que inspira pavor por su sola apariencia. Se aplica a la gran estatua (Dan 2:31) y a la cuarta bestia con dientes de hierro (Dan 7:7, 19). Las traducciones al español como «terrible» confirman un sentido constante de espanto monstruoso e imponente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91521, 'spa', 'Temiendo, temblando', 'Temiendo, temblando (participio activo con min-qodam): la experiencia de pavor ante una figura poderosa. En Dan 5:19 todos los pueblos temían ante Nabucodonosor; en Dan 6:26 Darío decreta que se tiemble ante el Dios de Daniel. El español «temiendo» capta la postura de temor reverente o atemorizado ante una autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91522, 'spa', 'Atemorizar, causar espanto', 'Atemorizar, causar espanto (Pael causativo): el sueño aterroriza activamente al rey. Dan 4:5 emplea el imperfecto Pael con sufijo pronominal: «me atemorizó». El español «y me atemorizó» conserva la fuerza causativa, señalando esta como la única ocurrencia donde el verbo tiene un agente (el sueño) que actúa sobre el sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91525, 'spa', 'Apremiar bajo compulsión', 'Ser impulsado o presionado con urgencia, apresurarse bajo coacción. El participio pasivo en Ester 3:15 y 8:14 describe correos reales despachados a toda prisa, movidos por decreto. En Ester 6:12 Hamán corre a casa humillado, y en 2 Crónicas 26:20 el leproso Uzías es expulsado del templo. El verbo implica de manera constante que una presión externa o la vergüenza impulsa el movimiento, no la voluntad propia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91527, 'spa', 'Suficiencia, bastante — Sentido nominal central', 'Suficiencia, bastante — Sentido nominal central: suficiencia, lo que basta, lo adecuado para una necesidad. Aparece en construcciones diversas: absoluta (Mal 3:10, ''hasta que no haya más suficiencia'', es decir, sin límite), con sufijos pronominales (דַּיָּם ''suficiente para ellos'') y con complementos genitivos (Éx 36:7, ''más que suficiente para la obra''). Concepto claro y universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91528, 'spa', 'Cada vez que, siempre que — Modismo temporal-frecuentativo מִדֵּי', 'Cada vez que, siempre que — Modismo temporal-frecuentativo מִדֵּי: ''cada vez que, siempre que, todas las veces que''. Extensión semántica genuina donde la noción de suficiencia se vuelve recurrencia iterativa. 1 Samuel 1:7 (''cada vez que subía a la casa del SEÑOR'') y 1 Reyes 14:28 ilustran esta función temporal claramente distinta del sentido cuantitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91533, 'spa', 'Conforme a, en proporción a — Modismo preposicional proporcional כְּדֵי', 'Conforme a, en proporción a — Modismo preposicional proporcional כְּדֵי: ''conforme a, en proporción a, tanto como corresponde''. Deuteronomio 25:2 prescribe azotes ''conforme a su culpa'' (כְּדֵי רִשְׁעָתוֹ), y Nehemías 5:8 habla de redimir ''tanto como estaba en nosotros''. Este sentido tiende un puente entre suficiencia y norma: no solo ''bastante'' sino ''en la medida justa''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91535, 'spa', 'Como, a semejanza de — Uso comparativo de כְּדֵי que significa ''como, a semejanz', 'Como, a semejanza de — Uso comparativo de כְּדֵי que significa ''como, a semejanza de'': atestiguado solo una vez, en Jueces 6:5, donde los madianitas vinieron ''como langostas en multitud''. Este es el mayor estiramiento semántico desde la noción raíz de suficiencia, llegando a la simple comparación, quizá a través del puente de la proporcionalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91551, 'spa', 'pronombre relativo (que/quien)', 'Pronombre relativo básico: ''que, quien, el cual'', introduciendo cláusulas relativas que modifican un sustantivo precedente (203 apariciones). Es la función primaria y más frecuente, directamente paralela al hebreo אֲשֶׁר. En Esdras 4:10-12, דִּי aparece repetidamente encadenando cláusulas relativas en correspondencia oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91552, 'spa', 'completiva (que/para que)', 'Complementante: ''que, para que'', introduciendo cláusulas de contenido tras verbos de decir, saber u ordenar, y cláusulas de propósito (75 apariciones). Se distingue del sentido 1 porque no modifica un sustantivo sino que subordina una cláusula completa. Daniel 2:30 ofrece un ejemplo claro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91553, 'spa', 'genitivo (de)', 'Marcador genitivo: ''de, perteneciente a'', funcionando como el estado constructo hebreo para expresar posesión, atribución o relación material (52 apariciones). ''El Dios del cielo'' (אֱלָהּ שְׁמַיָּא... דִּי), ''los vasos de la casa''. Concentrado en los documentos oficiales de Esdras y los decretos de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91556, 'spa', 'causal (porque)', 'Conjunción causal: ''porque, pues'', introduciendo cláusulas que explican la razón de algo (10 apariciones). Dn 2:47 (''porque pudiste revelar este misterio'') es un ejemplo claro. Se distingue nítidamente del uso relativo o completivo por su función explicativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91560, 'spa', 'temporal (cuando)', 'Conjunción temporal: ''cuando, al'', típicamente en la forma compuesta כְּדִי (ke-di, ''cuando''), introduciendo cláusulas temporales (5 apariciones). Dn 3:7 (''cuando todos los pueblos oyeron el sonido del cuerno'') y Dn 6:10 (''cuando Daniel supo que el documento había sido firmado'') son los casos representativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91561, 'spa', 'locativo (donde)', 'Relativo locativo: ''donde'', introduciendo cláusulas de lugar (2 apariciones). En Esdras 6:1 y 6:3, דִּי significa ''donde'' (el depósito donde se guardaban los tesoros). Aunque marginal en frecuencia, completa el paradigma de דִּי como subordinador universal del arameo bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91569, 'spa', 'Dibon (nombre de lugar)', 'Dibon (nombre de lugar): ciudad en el territorio de Moab, situada en la meseta al norte del desfiladero del Arnón. Capturada de Sijón y asignada a Gad (Nm 21:30; 32:3, 34), aparece en el itinerario del desierto como Dibon-Gad (Nm 33:45-46). Es el sitio donde se descubrió la Estela de Mesa. Los profetas apuntan contra Dibon en sus oráculos contra Moab (Is 15:2; Jer 48:18, 22), describiendo a sus habitantes llorando en los lugares altos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91581, 'spa', 'El sentido jurídico central', 'El sentido jurídico central: actuar como juez, dirimir una causa y pronunciar un veredicto. Domina las ocurrencias, desde Dios juzgando a las naciones (Gn 15:14; Dt 32:36) hasta los tribunales humanos (Jer 22:16). La unanimidad interlingüística es notable: español ''juzgar'', hindi ''न्याय करना'', árabe ''يدين'' y coreano ''심판하다'' convergen en la acción judicial formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91584, 'spa', 'Defender, vindicar o abogar por la causa de alguien', 'Defender, vindicar o abogar por la causa de alguien: el juicio ejercido no de forma neutral sino en favor del vulnerable. Proverbios 31:9 ordena ''juzga y defiende al pobre'', y el Salmo 54:1 suplica ''vindícame con tu poder''. Este sentido representa la faceta compasiva de la justicia: el juez como defensor del agraviado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91589, 'spa', 'Contender, luchar o disputar, frecuentemente en un contexto legal o adversarial', 'Contender, luchar o disputar, frecuentemente en un contexto legal o adversarial. Génesis 6:3 lo aplica al espíritu de Dios ''contendiendo'' con la humanidad, y 2 Samuel 19:9 describe a las tribus ''disputando'' entre sí. El Nifal recíproco refuerza esta cualidad mutua de confrontación, un ir y venir de la contienda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91592, 'spa', 'Sentido extendido de gobernar o regir, donde la autoridad judicial se transforma', 'Sentido extendido de gobernar o regir, donde la autoridad judicial se transforma en soberanía administrativa. Zacarías 3:7 promete al sumo sacerdote Josué que ''gobernará'' la casa de Dios. Es la extensión natural del tribunal a la sala del trono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91600, 'spa', 'El veredicto judicial, sentencia o acto de condena resultante de la deliberación', 'El veredicto judicial, sentencia o acto de condena resultante de la deliberación. En Ester 1:13 el rey consulta a quienes ''conocían la ley y el juicio''. Job reflexiona sobre ''el juicio y la justicia'' que lo han alcanzado (Job 36:17) y teme que ''el juicio esté ante'' los impíos (Job 19:29). El alemán ''Gericht'' y el francés ''jugement'' captan este sentido resultativo: no la causa en sí, sino la resolución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91601, 'spa', 'Causa legal, pleito o demanda presentada ante un juez para su resolución', 'Causa legal, pleito o demanda presentada ante un juez para su resolución. Deuteronomio 17:8 lo emplea para distinguir ''entre causa y causa'' en los tribunales. Jeremías acusa a los líderes de Israel por descuidar la causa del huérfano (Jer 5:28; 22:16), y el salmista confía en que Dios ''mantendrá mi causa'' (Sal 9:4; 140:12). El español ''causa'' y el francés ''cause'' traducen directamente este sentido forense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91614, 'spa', 'Juicio, justicia', 'Juicio, justicia o veredicto legal: el acto o resultado de dictar una decisión judicial. En Daniel 4:37 caracteriza los caminos de Dios como justos. Esdras 7:26 habla de juicio ejecutado sobre los infractores. El término oscila entre el sentido abstracto de justicia y el institucional de tribunal, como en Daniel 7:10 donde el tribunal celestial se sienta para juzgar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91617, 'spa', 'Dina (nombre propio)', 'Nombre personal de Dina, la hija de Jacob y Lea. Todas las traducciones transliteran el nombre de manera consistente: ''Dina'' o ''Diná'' en español, ''Dina'' en francés y alemán, con variaciones menores solo en prefijos preposicionales (''a Dina''). Las ocho apariciones se encuentran exclusivamente en Génesis: su nacimiento (30:21), el episodio de Siquem (34:1, 3, 5, 13, 25, 26) y la nota genealógica de quienes bajaron a Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91620, 'spa', 'Rampa de asedio', 'Muro o rampa de asedio erigido contra una ciudad sitiada, parte del aparato estándar de la guerra de sitio en el antiguo Cercano Oriente junto con terraplenes (סֹלְלָה) y arietes. El español ofrece varias traducciones — «baluarte», «cerco» y «rampa de asedio» — que reflejan la incertidumbre sobre la naturaleza exacta de la estructura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91625, 'spa', 'Disón', 'Disón, nombre personal horeo que llevan dos figuras emparentadas en las genealogías edomitas. El principal Disón es hijo de Seir el horeo (Gn 36:21; 1 Cr 1:38), incluido entre los jefes de clan originales de la tierra de Edom. Un segundo Disón es hijo de Aná y nieto de Seir (Gn 36:25, 30; 1 Cr 1:41). La transliteración es estable en las distintas lenguas: español «Disón», inglés «Dishon», francés y alemán conservan formas similares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91628, 'spa', 'Disán', 'Disán, variante del mismo nombre horeo que aparece en 1 Crónicas 1:42, donde el Cronista enumera a los hijos de este jefe de clan. BDB distingue la grafía con nun final (Disán) de la más común Disón, aunque se refieren a la misma figura genealógica. Inglés «Dishan» y español «Disán» preservan esta distinción en la transliteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91630, 'spa', 'Disán (nombre propio)', 'Nombre personal Disán, que identifica a un jefe horeo e hijo de Seír. Sus cinco apariciones se hallan en listas genealógicas (Gn 36:21, 26, 28, 30; 1 Cr 1:38). La Septuaginta lo transcribe como Ρισων, reflejando una tradición fonética alternativa. Las variantes textuales a veces confunden a este personaje con Disón, su casi homónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91631, 'spa', 'Oprimido y desvalido', 'Oprimido, aplastado, abatido: describe a personas social o físicamente sometidas que necesitan la vindicación divina. Los Salmos emparejan este término con el huérfano (יָתוֹם) y el pobre (עָנִי, אֶבְיוֹן), como en Sal 10:18 donde Dios se levanta para juzgar a favor del oprimido. En Prov 26:28 la misma raíz se extiende a quienes son aplastados por una lengua engañosa, mostrando que la opresión puede ser tanto verbal como física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91632, 'spa', 'Este/esta (demostrativo)', 'Pronombre demostrativo pospositivo que significa ''este/esta'', funcionando como modificador deíctico que sigue a su sustantivo. En la correspondencia imperial de Esdras, especifica el referente bajo discusión legal: ''esta ciudad'' rebelde (Esd 4:13, 15-16, 19, 21), ''esta casa de Dios'' cuya reconstrucción se decreta (Esd 5:16-17; 6:7-8, 12). La forma es cognada con el árabe dhaka y el etíope zeku.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91633, 'spa', 'Ser aplastado (pasivo)', 'Ser aplastado (pasivo): sentido pasivo del Pual y Hitpael, ser aplastado, quebrado o destruido sin recurso. Los amigos de Job observan que los mortales que habitan en casas de barro son aplastados antes que la polilla (Job 4:19). Las formas pasivas dominan en los discursos de Job, expresando vulnerabilidad ante fuerzas que superan el control humano. En Isa 19:10, los cimientos de Egipto son aplastados.');